;","  // Lanes own ascending chunks, so a strict comparison keeps the lowest row on ties.","  if (laneBoundsMin[laneIndex].x < (*ring).boundsMin.x) {","    (*ring).extremeRows.x = laneExtremeRows[laneIndex].x;","  if (laneBoundsMin[laneIndex].y < (*ring).boundsMin.y) {","    (*ring).extremeRows.y = laneExtremeRows[laneIndex].y;","  if (laneBoundsMax[laneIndex].x > (*ring).boundsMax.x) {","    (*ring).extremeRows.z = laneExtremeRows[laneIndex].z;","  if (laneBoundsMax[laneIndex].y > (*ring).boundsMax.y) {","    (*ring).extremeRows.w = laneExtremeRows[laneIndex].w;","  (*ring).boundsMin = min((*ring).boundsMin, laneBoundsMin[laneIndex]);","  (*ring).boundsMax = max((*ring).boundsMax, laneBoundsMax[laneIndex]);","fn writeFeatureStats(index: u32, origin: vec2<f32>, acc: FeatureAccumulators) {","  let crossSum = getCompensated(acc.areaSum);","  let totalLength = getCompensated(acc.lengthSum);","  let isInvalid = acc.invalidRings > 0u;","  var centroid = acc.vertexSum / f32(acc.vertexCount);","  let straightCrossSum = getCompensated(acc.straightSum);","    centroid = vec2<f32>(getCompensated(acc.momentX), getCompensated(acc.momentY)) / (3.0 * straightCrossSum);","    centroid = vec2<f32>(getCompensated(acc.lineMomentX), getCompensated(acc.lineMomentY)) / totalLength;","  writeStat(index, 5u, origin.x + acc.boundsMin.x);","  writeStat(index, 6u, origin.y + acc.boundsMin.y);","  writeStat(index, 7u, origin.x + acc.boundsMax.x);","  writeStat(index, 8u, origin.y + acc.boundsMax.y);","  featureStats[featureStatsOffset + index * STATS_STRIDE + 9u] = acc.vertexCount;","    featureStats[featureStatsOffset + index * STATS_STRIDE + 11u + slot] = acc.extremeRows[slot];","  featureStats[featureStatsOffset + index * STATS_STRIDE + 15u] = acc.invalidRings;","// Wrapped longitude step into vertex k of a ring (vertex 0 steps from the feature origin).","fn getLongitudeStep(rowBegin: u32, vertex: u32, origin: vec2<f32>) -> f32 {","  let current = getPosition(rowBegin + vertex);","  if (vertex == 0u) {","    return geodesicWrapLongitudeDelta(current.x - origin.x);","  return lonLatRingStep(getPosition(rowBegin + vertex - 1u), current);","// Measures one cooperative feature with the whole workgroup. Called from uniform control flow.","fn measureFeatureCooperatively(feature: u32, lane: u32) {","  if (lane == 0u) {","    for (var ring = range.x; ring < range.y; ring++) {","      let rows = getRingRows(ring);","      if (rows.y > 0u) {","        sharedOrigin = getPosition(rows.x);","    sharedRingEnd = range.y;","  let ringEnd = workgroupUniformLoad(&sharedRingEnd);","  let origin = workgroupUniformLoad(&sharedOrigin);","  var accumulated = initFeature();","  var ring = range.x;","  loop {","    if (lane == 0u) {","      // Small rings are lane 0's: no barriers until the next large ring.","      while (ring < ringEnd) {","        let rows = getRingRows(ring);","        if (rows.y > COOPERATIVE_RING_ROWS) {","          break;","        if (rows.y > 0u) {","          var smallRing = initRing();","          let firstPosition = getPosition(rows.x);","          accumulateRange(","            rows.x, rows.y, 0u, rows.y,","            geodesicWrapLongitudeDelta(firstPosition.x - origin.x), origin, &smallRing","          );","          mergeRing(&accumulated, &smallRing, ring, rows.y);","        ring++;","      sharedRing = ring;","    let current = workgroupUniformLoad(&sharedRing);","    if (current >= ringEnd) {","    let rows = getRingRows(current);","    let chunk = (rows.y + COOPERATIVE_LANES - 1u) / COOPERATIVE_LANES;","    let vertexStart = min(lane * chunk, rows.y);","    let vertexEnd = min(vertexStart + chunk, rows.y);","    var startLocalX = 0.0;","    if (IS_GEOGRAPHIC && !IS_POINT) {","      // Unwrapped longitude of the chunk's first vertex: exclusive scan of the chunks' sums of","      // wrapped longitude steps (Hillis-Steele in workgroup memory).","      var stepSum = vec2<f32>(0.0);","      for (var vertex = vertexStart; vertex < vertexEnd; ve